import {ToolRegistry} from './registry.js';
import {jest} from '@jest/globals';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry validation of extra properties', () => {
  it('passes the input object through unchanged including undeclared extra properties. ([validated by src/orchestration/tools/registry.test.ts#L7])', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'echo',
        description: 'echoes',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async input => {
        executorInputs.push(input);
        return 'ok';
      }
    );

    await registry.execute('echo', {a: 'hello', b: 'extra'});
    expect(executorInputs).toEqual([{a: 'hello', b: 'extra'}]);
  });
});

describe('ToolRegistry input validation statements', () => {
  it('throws Unknown tool: <name> when execute is called with a tool name that has not been registered. ([validated by src/orchestration/tools/registry.test.ts#L27])', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('unregistered_tool', {})).rejects.toThrow('Unknown tool: unregistered_tool');
  });

  it('compiles static tool inputSchema at register time and reuses it on every execute call without re-reading. ([validated by src/orchestration/tools/registry.test.ts#L32])', async () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {foo: {type: 'string'}}};

    // Using a getter to spy on re-reads if it were re-read
    let readCount = 0;
    const definition: ToolDefinition = {
      name: 'static_tool',
      description: 'static',
      get inputSchema() {
        readCount++;
        return schema;
      }
    };

    registry.register(definition, async () => 'ok');
    const initialReads = readCount; // 1 for compilation

    await registry.execute('static_tool', {foo: 'bar'});
    await registry.execute('static_tool', {foo: 'baz'});

    // Should not have read `inputSchema` again on execute
    expect(readCount).toBe(initialReads);
  });

  it('resolves function-valued ToolDefinitionSource on each execute and caches compiled validators by schema object reference. ([validated by src/orchestration/tools/registry.test.ts#L54])', async () => {
    const registry = new ToolRegistry();
    const schemaA = {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};
    const schemaB = {type: 'object', properties: {b: {type: 'string'}}, required: ['b']};

    let callCount = 0;
    registry.register(() => {
      callCount++;
      return {
        name: 'dynamic_tool',
        description: 'dynamic',
        inputSchema: callCount % 2 === 1 ? schemaA : schemaB,
      };
    }, async () => 'ok');

    // First call uses schemaA, expects 'a'
    const res1 = await registry.execute('dynamic_tool', {b: 'hello'});
    expect(res1.result).toMatch(/Invalid input/);
    expect(res1.result).toMatch(/a/);

    // Second call uses schemaB, expects 'b'
    const res2 = await registry.execute('dynamic_tool', {a: 'hello'});
    expect(res2.result).toMatch(/Invalid input/);
    expect(res2.result).toMatch(/b/);

    // Verify it resolved the definition on each execute
    expect(callCount).toBe(2);
  });
});
